begin;
grant select,insert,update,delete on public.department_kpi_configs to authenticated;
alter table public.department_kpi_configs enable row level security;
select check_ok(not exists(select 1 from department_receiving_settings),'no departments enabled by migration');
select check_ok(not exists(select 1 from department_sla_managers),'no managers auto-assigned');
select check_ok((select pg_get_constraintdef(oid)='PRIMARY KEY (id)' from pg_constraint where conrelid='department_sla_managers'::regclass and contype='p'),'grant junction cannot infer an ambiguous profile department embedding');
create temp table old_snapshot as select id,sla_policy_snapshot from surat_signatures;
insert into department_receiving_weekly_rules(dept_id,enabled,message,sla_minutes)
 values(tid(2),true,'Penerimaan ditutup Kamis16.00.',40);
select check_ok((department_receiving_policy(tid(2),'2026-11-05T16:00:00+07:00')#>>'{receiving,available_at}')::timestamptz='2026-11-05T16:00:00+07:00','department reception stays off without explicit setting');
select check_ok((department_receiving_policy(tid(2),'2026-11-05T16:00:00+07:00')->>'sla_minutes')::integer=120,'off preserves existing signer SLA');
insert into department_receiving_settings(dept_id,enabled) values(tid(2),true);
select check_ok((department_receiving_policy(tid(2),'2026-11-05T15:59:59+07:00')#>>'{receiving,available_at}')::timestamptz='2026-11-05T15:59:59+07:00','Thursday before cutoff immediate');
select check_ok((department_receiving_policy(tid(2),'2026-11-05T16:00:00+07:00')#>>'{receiving,available_at}')::timestamptz='2026-11-09T08:00:00+07:00','exact Thursday16 cutoff defers to Monday');
update department_receiving_weekly_rules set open_time='00:00',cutoff_weekday=1,cutoff_time='00:01' where dept_id=tid(2);
do $$begin begin perform department_receiving_policy(tid(2),'2026-11-05T16:00:00+07:00');exception when object_not_in_prerequisite_state then return;end;raise exception 'impossible weekly calendar accepted';end$$;
update department_receiving_weekly_rules set open_time='08:00',cutoff_weekday=4,cutoff_time='16:00' where dept_id=tid(2);
select check_ok((department_receiving_policy(tid(2),'2026-11-06T10:00:00+07:00')#>>'{receiving,period_week}')::date='2026-11-09','period records next ISO week');
select check_ok((department_receiving_policy(tid(2),'2026-12-31T16:00:00+07:00')#>>'{receiving,available_at}')::timestamptz='2027-01-04T08:00:00+07:00','ISO year boundary');
insert into department_receiving_weekly_rules(dept_id,week_start,enabled,cutoff_weekday,cutoff_time,sla_minutes)
 values(tid(2),'2026-11-02',true,3,'14:00',25);
select check_ok((department_receiving_policy(tid(2),'2026-11-05T10:00:00+07:00')#>>'{receiving,available_at}')::timestamptz='2026-11-09T08:00:00+07:00','specific week override');
select check_ok((department_receiving_policy(tid(2),'2026-11-05T10:00:00+07:00')->>'sla_minutes')::integer=40,'next-week SLA overrides previous exception');
update department_receiving_weekly_rules set enabled=false where week_start='2026-11-02';
select check_ok((department_receiving_policy(tid(2),'2026-11-06T10:00:00+07:00')#>>'{receiving,available_at}')::timestamptz='2026-11-06T10:00:00+07:00','disabled specific week bypasses regular weekly window');
delete from department_receiving_weekly_rules where week_start='2026-11-02';
insert into holidays values('2026-11-09');
select check_ok((department_receiving_policy(tid(2),'2026-11-05T16:00:00+07:00')#>>'{receiving,available_at}')::timestamptz='2026-11-10T08:00:00+07:00','holiday respects work calendar');
select check_ok((department_receiving_policy(tid(2),'2026-11-05T12:30:00+07:00')#>>'{receiving,available_at}')::timestamptz='2026-11-05T13:00:00+07:00','break resumes same open week');
insert into department_receiving_rules(dept_id,enabled,cutoff_day,cutoff_time,reopen_day)
 values(tid(2),true,25,'15:00',1);
select check_ok((department_receiving_policy(tid(2),'2026-11-26T10:00:00+07:00')#>>'{receiving,available_at}')::timestamptz='2026-12-01T08:00:00+07:00','monthly close and weekly window intersect');
select check_ok((select bool_and(s.sla_policy_snapshot is not distinct from old.sla_policy_snapshot) from surat_signatures s join old_snapshot old using(id)),'no old snapshots rewritten');
insert into department_receiving_weekly_rules(dept_id,week_start,enabled,open_weekday,open_time,cutoff_weekday,cutoff_time,sla_minutes)
 values(tid(2),date_trunc('week',now() at time zone 'Asia/Jakarta')::date,true,1,'00:00',1,'00:01',35);
insert into surat_signatures(id,surat_id,user_id,step_order,available_at) values(tid(960),tid(13),tid(3),2,now());
select check_ok((select available_at>now() and sla_policy_snapshot->>'version'='2' from surat_signatures where id=tid(960)),'new stage captures weekly hold');
create temp table frozen_week as select sla_policy_snapshot from surat_signatures where id=tid(960);
update department_receiving_settings set enabled=false where dept_id=tid(2);
update surat_signatures set available_at=null,sla_policy_snapshot='{}' where id=tid(960);
select check_ok((select s.available_at>now() and s.sla_policy_snapshot=w.sla_policy_snapshot from surat_signatures s cross join frozen_week w where s.id=tid(960)),'disabling policy cannot rewrite existing hold or frozen SLA');
do $$begin begin update surat_signatures set is_signed=true where id=tid(960);exception when object_not_in_prerequisite_state then return;end;raise exception 'weekly hold signed early';end$$;
insert into surat_signatures(id,surat_id,user_id,step_order,available_at) values(tid(961),tid(13),tid(3),3,now());
select check_ok((select available_at<=now() and not (sla_policy_snapshot#>>'{receiving,enabled}')::boolean from surat_signatures where id=tid(961)),'future stages bypass intake when disabled');
update department_receiving_settings set enabled=true where dept_id=tid(2);
do $$begin begin insert into department_receiving_weekly_rules(dept_id,week_start) values(tid(2),'2026-11-10');exception when check_violation then return;end;raise exception 'non-Monday week accepted';end$$;
do $$begin begin insert into department_receiving_weekly_rules(dept_id,week_start,open_weekday,cutoff_weekday) values(tid(2),'2026-11-16',5,2);exception when check_violation then return;end;raise exception 'inverted week accepted';end$$;

select set_config('request.jwt.claim.sub',tid(1)::text,true);set local role authenticated;
select check_ok(not can_manage_department_sla(tid(1)) and not exists(select 1 from get_department_sla_scope()),'unassigned employee has no management scope');
do $$begin begin insert into department_receiving_settings(dept_id) values(tid(1));exception when insufficient_privilege then return;end;raise exception 'unassigned staff wrote settings';end$$;
do $$begin begin perform set_department_sla_managers(tid(1),array[tid(1)]);exception when insufficient_privilege then return;end;raise exception 'staff self-granted';end$$;
reset role;select set_config('request.jwt.claim.sub',tid(9)::text,true);set local role authenticated;
select set_department_sla_managers(tid(2),array[tid(3)]);
reset role;
create temp table audit_before_repeat as select count(*) n from department_policy_events;
set local role authenticated;
select set_department_sla_managers(tid(2),array[tid(3)]);
reset role;
select check_ok((select count(*)=(select n from audit_before_repeat) from department_policy_events),'repeated grant has no phantom insert audit');
set local role authenticated;
select check_ok((select count(*)=2 from get_department_sla_scope()),'admin scope includes all departments');
select check_ok((select count(*)=1 and bool_and(selected) from get_department_sla_manager_candidates(tid(2))),'candidate list scoped to active department members');
do $$begin begin perform set_department_sla_managers(tid(2),array[tid(1)]);exception when invalid_parameter_value then return;end;raise exception 'foreign member assigned';end$$;
reset role;select set_config('request.jwt.claim.sub',tid(3)::text,true);set local role authenticated;
select check_ok((select count(*)=1 and bool_and(dept_id=tid(2)) from get_department_sla_scope()),'delegate sees only assigned department');
update department_receiving_settings set enabled=false where dept_id=tid(2);
insert into department_receiving_weekly_rules(dept_id,week_start) values(tid(2),'2026-11-09');
update department_receiving_rules set sla_minutes=80 where dept_id=tid(2);
update department_kpi_configs set sla_minutes=90 where dept_id=tid(2);
select check_ok(exists(select 1 from department_policy_events where actor_id=tid(3) and entity='department_kpi_configs'
 and after_data->>'sla_minutes'='90'),'delegate SLA edit audited');
select check_ok(exists(select 1 from department_policy_events where actor_id=tid(3) and entity='department_receiving_settings'),'delegate settings edit audited');
reset role;
create temp table audit_before_ignore as select count(*) n from department_policy_events;
set local role authenticated;
insert into department_receiving_weekly_rules(dept_id) values(tid(2)) on conflict do nothing;
reset role;
select check_ok((select count(*)=(select n from audit_before_ignore) from department_policy_events),'conflict ignore has no phantom policy audit');
create temp table monthly_audit_before as select count(*) n from department_receiving_rule_events;
set local role authenticated;
insert into department_receiving_rules(dept_id) values(tid(2)) on conflict do nothing;
reset role;
select check_ok((select count(*)=(select n from monthly_audit_before) from department_receiving_rule_events),'monthly conflict ignore has no phantom audit');
set local role authenticated;
insert into department_receiving_rules(dept_id,sla_minutes) values(tid(2),91)
 on conflict(dept_id,period_month) do update set sla_minutes=excluded.sla_minutes;
reset role;
select check_ok((select count(*)=(select n+1 from monthly_audit_before) from department_receiving_rule_events),'monthly conflict update writes one persisted audit');
select check_ok(exists(select 1 from department_receiving_rule_events where actor_id=tid(3) and before_data->>'sla_minutes'='80' and after_data->>'sla_minutes'='91' and after_data->>'updated_by'=tid(3)::text),'monthly update audit matches actor and persisted values');
set local role authenticated;
do $$begin begin insert into department_receiving_weekly_rules(dept_id) values(tid(1));exception when insufficient_privilege then return;end;raise exception 'delegate changed foreign week';end$$;
do $$begin begin perform set_department_sla_managers(tid(2),array[tid(3)]);exception when insufficient_privilege then return;end;raise exception 'delegate can assign peers';end$$;
do $$begin begin delete from department_policy_events;exception when insufficient_privilege then return;end;raise exception 'delegate erased audit';end$$;
do $$begin begin insert into department_sla_managers(dept_id,user_id) values(tid(1),tid(3));exception when insufficient_privilege then return;end;raise exception 'delegate granted directly';end$$;
reset role;
select check_ok((department_receiving_policy(tid(2),'2026-11-06T10:00:00+07:00')->>'sla_minutes')::integer=90,'disabled intake uses current signer SLA not receiving overrides');
update profiles set department_id=tid(1) where id=tid(3);
set local role authenticated;
select check_ok(not can_manage_department_sla(tid(2)) and not exists(select 1 from get_department_sla_scope()),'transfer immediately removes old department grant access');
reset role;update profiles set department_id=tid(2),is_active=false where id=tid(3);set local role authenticated;
select check_ok(not can_manage_department_sla(tid(2)),'inactive delegate denied');
reset role;update profiles set is_active=true where id=tid(3);
select set_config('request.jwt.claim.sub',tid(9)::text,true);set local role authenticated;
select set_department_sla_managers(tid(2),'{}');
reset role;select set_config('request.jwt.claim.sub',tid(3)::text,true);set local role authenticated;
select check_ok(not can_manage_department_sla(tid(2)),'revocation immediate');
reset role;select set_config('request.jwt.claim.sub','',true);set local role anon;
do $$begin begin perform get_department_sla_scope();exception when insufficient_privilege then return;end;raise exception 'anonymous management scope accepted';end$$;
reset role;
select check_ok(not has_function_privilege('authenticated','public.department_receiving_policy(uuid,timestamptz)','execute'),'clock stays internal');
select 'SLA02 weekly receiving and delegated management passed';
rollback;
